function rows(name) {
  try { return $(name).all().map(function (i) { return i.json; }).filter(function (j) { return j && j.id !== undefined; }); } catch (e) { return []; }
}
function esc(s) { return String(s === null || s === undefined ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); }
function num(v) { var n = Number(v); return (v === null || v === undefined || v === '' || !isFinite(n)) ? null : n; }
function fmt(v, d) { var n = num(v); return n === null ? 'n/a' : n.toFixed(d === undefined ? 0 : d); }
var now = Date.now();
function ageH(iso) { var t = Date.parse(iso); return isFinite(t) ? (now - t) / 3600000 : null; }
function local(iso) { var t = Date.parse(iso); if (!isFinite(t)) return 'n/a'; return new Date(t).toLocaleString('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'medium', timeStyle: 'short' }) + ' PKT'; }

var cfg = $('Run Config').first().json;
var hot = rows('Read Hotspots');
var cams = rows('Read Grid Readings');
var aq = rows('Read Ground Sensors');
var fires = rows('Read Fires');
var fc = rows('Read Forecast');
var logs = rows('Read Pull Log');

var CATS = [
  [12, 'Good', '#2e7d32', '#e8f5e9', 'Air is fine for everyone.'],
  [35.5, 'Moderate', '#8a6d00', '#fffde7', 'Very sensitive people should avoid long hard exercise outdoors.'],
  [55.5, 'Unhealthy for sensitive groups', '#e65100', '#fff3e0', 'Children, elderly people, pregnant women and anyone with asthma or heart disease should stay indoors.'],
  [150.5, 'Unhealthy', '#c62828', '#ffebee', 'Everyone should cut down time outdoors. Wear an N95 mask if you must go out.'],
  [250.5, 'Very unhealthy', '#6a1b9a', '#f3e5f5', 'Avoid going outside. Keep windows closed.'],
  [1000000, 'Hazardous', '#4a148c', '#ede7f6', 'Emergency conditions. Stay indoors and use a mask outside.']
];
function cat(p) {
  if (p === null) return { name: 'No current data', color: '#616161', bg: '#eeeeee', advice: 'No fresh reading is available right now.' };
  for (var i = 0; i < CATS.length; i++) { if (p < CATS[i][0]) return { name: CATS[i][1], color: CATS[i][2], bg: CATS[i][3], advice: CATS[i][4] }; }
  return { name: 'Hazardous', color: '#4a148c', bg: '#ede7f6', advice: '' };
}
function badge(p) { var c = cat(p); return '<span style="background:' + c.color + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:12px;white-space:nowrap">' + esc(c.name) + '</span>'; }

// Place in plain words, relative to central Lahore
var LAT0 = 31.52, LON0 = 74.35;
function place(lat, lon) {
  var la = num(lat), lo = num(lon);
  if (la === null || lo === null) return 'Unknown location';
  var dn = (la - LAT0) * 111, de = (lo - LON0) * 95;
  var d = Math.sqrt(dn * dn + de * de);
  if (d < 6) return 'Central Lahore';
  var ang = Math.atan2(de, dn) * 180 / Math.PI; if (ang < 0) ang += 360;
  var names = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
  return Math.round(d) + ' km ' + names[Math.round(ang / 45) % 8] + ' of central Lahore';
}
function gmap(lat, lon) { return 'https://www.google.com/maps?q=' + lat + ',' + lon; }

// Latest fresh grid reading per cell, latest fresh sensor per station
function latestFresh(list, maxAge, key) {
  var seen = {}; var out = [];
  list.slice().sort(function (a, b) { return Date.parse(b.observed_at) - Date.parse(a.observed_at); }).forEach(function (o) {
    var k = o[key]; if (seen[k]) return; seen[k] = true;
    var a = ageH(o.observed_at); if (a !== null && a <= maxAge && num(o.pm25) !== null) out.push(o);
  });
  return out;
}
var cells = latestFresh(cams, 4, 'cell_id');
var sensors = latestFresh(aq, 3, 'cell_id');

var near = cells.filter(function (c) { return Math.abs(Number(c.lat) - LAT0) <= 0.25 && Math.abs(Number(c.lon) - LON0) <= 0.3; });
var basis = near.length ? near : cells;
var modelAvg = basis.length ? basis.reduce(function (s, c) { return s + Number(c.pm25); }, 0) / basis.length : null;
var sv = sensors.map(function (s) { return Number(s.pm25); }).sort(function (a, b) { return a - b; });
var sensorMed = sv.length ? (sv.length % 2 ? sv[(sv.length - 1) / 2] : (sv[sv.length / 2 - 1] + sv[sv.length / 2]) / 2) : null;
var headline = sensorMed !== null ? sensorMed : modelAvg;
var hc = cat(headline);

// Source health
var latest = {};
logs.slice().sort(function (a, b) { return Date.parse(b.run_at) - Date.parse(a.run_at); }).forEach(function (l) { if (!latest[l.source]) latest[l.source] = l; });
var specs = [
  ['open-meteo-cams', 'Air quality model (CAMS via Open-Meteo)', 3, true],
  ['open-meteo-weather', 'Weather and wind (Open-Meteo)', 3, true],
  ['nasa-firms', 'NASA satellite fire detections', 3, true],
  ['openaq', 'Ground air-quality sensors (OpenAQ)', 3, false],
  ['osm-facilities', 'Factory and kiln map (OpenStreetMap)', 240, false],
  ['detection', 'Hotspot detection', 3, true],
  ['forecast', '12-hour forecast model', 8, true]
];
var srcRows = ''; var problems = [];
for (var s = 0; s < specs.length; s++) {
  var sp = specs[s]; var l = latest[sp[0]];
  var state = 'No data yet'; var col = '#c62828'; var when = 'never';
  if (l) {
    var a = ageH(l.run_at); when = local(l.run_at);
    if (l.status === 'ok' && a !== null && a <= sp[2]) { state = 'Working'; col = '#2e7d32'; }
    else if (l.status === 'ok') { state = 'Out of date (' + Math.round(a) + ' h old)'; col = '#c62828'; }
    else if (l.status === 'partial') { state = 'Partly working'; col = '#e65100'; }
    else { state = 'Failed'; col = '#c62828'; }
  }
  if (col !== '#2e7d32' && sp[3]) problems.push(sp[1] + ': ' + state);
  srcRows += '<tr><td style="padding:6px;border-bottom:1px solid #eee;font-size:13px">' + esc(sp[1]) + '</td><td style="padding:6px;border-bottom:1px solid #eee;font-size:13px;color:' + col + ';font-weight:bold">' + esc(state) + '</td><td style="padding:6px;border-bottom:1px solid #eee;font-size:12px;color:#666">' + esc(when) + '</td></tr>';
}

// Hotspots from latest successful detection only
var det = latest['detection'];
var detOk = det && det.status === 'ok' && ageH(det.run_at) !== null && ageH(det.run_at) <= 3;
var shown = detOk ? hot.filter(function (h) { return h.run_id === det.run_id; }) : [];
shown.sort(function (x, y) { return Number(y.priority_score) - Number(x.priority_score); });

function causeKey(a) {
  var t = String(a || '').toLowerCase();
  if (t.indexOf('crop') >= 0 || t.indexOf('biomass') >= 0) return 'burn';
  if (t.indexOf('kiln') >= 0) return 'kiln';
  if (t.indexOf('industr') >= 0) return 'ind';
  return 'unk';
}
var CAUSE = {
  burn: ['Crop-residue burning', '#e65100', 'Farmers burning leftover rice or wheat stalks. Satellites saw fires upwind of the smoky area.'],
  kiln: ['Brick kilns', '#6d4c41', 'Brick kilns burning fuel close to the smoky area.'],
  ind: ['Factories and industry', '#455a64', 'Many industrial sites sit near the smoky area and no nearby fires were seen.'],
  unk: ['Not clear yet', '#9e9e9e', 'Could be traffic, smoke drifting in from far away, or other local sources. Needs a field check.']
};
var counts = { burn: 0, kiln: 0, ind: 0, unk: 0 };
shown.forEach(function (h) { counts[causeKey(h.attribution)]++; });
var total = shown.length;
var causeHtml = '';
if (total) {
  ['burn', 'kiln', 'ind', 'unk'].forEach(function (k) {
    if (!counts[k]) return;
    var pct = Math.round(counts[k] / total * 100);
    causeHtml += '<tr><td style="padding:8px 0"><div style="font-size:14px;font-weight:bold;color:#222">' + esc(CAUSE[k][0]) + ' <span style="font-weight:normal;color:#666">- ' + counts[k] + ' of ' + total + ' hotspots (' + pct + '%)</span></div>';
    causeHtml += '<table width="100%" cellpadding="0" cellspacing="0" style="margin:4px 0"><tr><td width="' + pct + '%" style="background:' + CAUSE[k][1] + ';height:12px;font-size:1px;line-height:12px;border-radius:6px">&nbsp;</td><td style="background:#eceff1;height:12px;font-size:1px;line-height:12px">&nbsp;</td></tr></table>';
    causeHtml += '<div style="font-size:12px;color:#555">' + esc(CAUSE[k][2]) + '</div></td></tr>';
  });
} else {
  causeHtml = '<tr><td style="padding:8px 0;font-size:13px;color:#555">' + (detOk ? 'No area crossed the smoke-hotspot threshold in the latest check.' : 'No current cause list: the latest hotspot check is missing, failed or out of date. Older results are hidden on purpose so they are not mistaken for current ones.') + '</td></tr>';
}

// Hotspot cards
var hotHtml = '';
shown.slice(0, 8).forEach(function (h, idx) {
  var ck = causeKey(h.attribution);
  var conf = h.attribution_confidence === 'high' ? 'fairly sure' : h.attribution_confidence === 'medium' ? 'moderately sure' : 'not very sure';
  hotHtml += '<tr><td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top;width:34px"><div style="background:' + cat(num(h.pm25)).color + ';color:#fff;border-radius:50%;width:28px;height:28px;line-height:28px;text-align:center;font-weight:bold">' + (idx + 1) + '</div></td>';
  hotHtml += '<td style="padding:10px;border-bottom:1px solid #eee;vertical-align:top"><div style="font-size:14px;font-weight:bold">' + esc(place(h.lat, h.lon)) + ' <a href="' + esc(gmap(h.lat, h.lon)) + '" style="font-size:12px;font-weight:normal;color:#1565c0">view on map</a></div>';
  hotHtml += '<div style="margin:3px 0">' + badge(num(h.pm25)) + ' <span style="font-size:12px;color:#555">PM2.5 ' + fmt(h.pm25) + ' ug/m3</span></div>';
  hotHtml += '<div style="font-size:13px">Likely cause: <b>' + esc(CAUSE[ck][0]) + '</b> <span style="color:#666">(' + conf + ')</span></div>';
  hotHtml += '<div style="font-size:12px;color:#666;margin-top:2px">Fires seen upwind: ' + esc(h.fires_upwind) + ' | industrial sites nearby: ' + esc(h.facilities_nearby) + (num(h.ground_pm25) !== null ? ' | nearest ground sensor reads ' + fmt(h.ground_pm25) : '') + (h.ground_agreement ? ' (' + esc(h.ground_agreement) + ')' : '') + '</div></td></tr>';
});
if (!hotHtml) hotHtml = '<tr><td style="padding:10px;font-size:13px;color:#555">No hotspots to show right now.</td></tr>';

// Heat grid (email-safe, no images)
var latKeys = {}; var lonKeys = {};
cells.forEach(function (c) { latKeys[Number(c.lat).toFixed(3)] = 1; lonKeys[Number(c.lon).toFixed(3)] = 1; });
var lats = Object.keys(latKeys).sort(function (a, b) { return Number(b) - Number(a); });
var lons = Object.keys(lonKeys).sort(function (a, b) { return Number(a) - Number(b); });
var byPos = {};
cells.forEach(function (c) { byPos[Number(c.lat).toFixed(3) + '|' + Number(c.lon).toFixed(3)] = c; });
var gridHtml = '';
if (cells.length) {
  gridHtml = '<table cellpadding="0" cellspacing="2" style="margin:0 auto"><tr><td></td><td colspan="' + lons.length + '" style="text-align:center;font-size:11px;color:#666">WEST to EAST</td></tr>';
  lats.forEach(function (la, ri) {
    gridHtml += '<tr><td style="font-size:10px;color:#666;padding-right:4px;text-align:right">' + (ri === 0 ? 'North' : ri === lats.length - 1 ? 'South' : '') + '</td>';
    lons.forEach(function (lo) {
      var c = byPos[la + '|' + lo]; var p = c ? Number(c.pm25) : null; var k = cat(p);
      var central = Math.abs(Number(la) - LAT0) <= 0.07 && Math.abs(Number(lo) - LON0) <= 0.09;
      gridHtml += '<td style="background:' + k.color + ';color:#fff;width:62px;height:44px;text-align:center;font-size:13px;font-weight:bold;border-radius:4px' + (central ? ';border:3px solid #111' : '') + '">' + (p === null ? '-' : fmt(p)) + '</td>';
    });
    gridHtml += '</tr>';
  });
  gridHtml += '</table><div style="text-align:center;font-size:11px;color:#666;margin-top:6px">Each square is about 14 km x 14 km. Number = PM2.5 (ug/m3). Black outline = central Lahore. Darker red/purple = smokier air.</div>';
} else {
  gridHtml = '<div style="font-size:13px;color:#555">No fresh air-quality map data right now.</div>';
}

// Ground sensors
var worst = sensors.slice().sort(function (a, b) { return Number(b.pm25) - Number(a.pm25); }).slice(0, 5);
var sensHtml = '';
worst.forEach(function (o) {
  sensHtml += '<tr><td style="padding:5px;border-bottom:1px solid #eee;font-size:13px">' + esc(place(o.lat, o.lon)) + ' <a href="' + esc(gmap(o.lat, o.lon)) + '" style="font-size:11px;color:#1565c0">map</a></td><td style="padding:5px;border-bottom:1px solid #eee;font-size:13px;font-weight:bold">' + fmt(o.pm25) + '</td><td style="padding:5px;border-bottom:1px solid #eee">' + badge(Number(o.pm25)) + '</td></tr>';
});
if (!sensHtml) sensHtml = '<tr><td style="padding:6px;font-size:13px;color:#555">No fresh ground-sensor readings.</td></tr>';

// Forecast in plain words
var fcHtml = '<div style="font-size:13px;color:#555">No forecast has been produced yet.</div>';
var f0 = fc.length ? fc.slice().sort(function (a, b) { return Date.parse(b.issued_at) - Date.parse(a.issued_at); })[0] : null;
if (f0) {
  var fAge = ageH(f0.issued_at);
  var pm = num(f0.pm25_model), pn = num(f0.pm25_now);
  var trend = 'about the same';
  if (pm !== null && pn !== null) { if (pm > pn * 1.1) trend = 'getting worse'; else if (pm < pn * 0.9) trend = 'getting better'; }
  var fk = cat(pm);
  if (fAge === null || fAge > 8) {
    fcHtml = '<div style="background:#ffebee;border:1px solid #c62828;color:#c62828;padding:8px;font-size:13px;font-weight:bold">The latest forecast is out of date (' + (fAge === null ? '?' : Math.round(fAge)) + ' hours old) and is hidden so it is not mistaken for current.</div>';
  } else {
    fcHtml = '<div style="font-size:15px">By <b>' + esc(local(f0.target_time)) + '</b> central Lahore air is expected to be <b style="color:' + fk.color + '">' + esc(fk.name) + '</b> (about ' + fmt(pm) + ' ug/m3), ' + trend + ' compared with now (' + fmt(pn) + ').</div>';
    var beats = f0.beats_baselines === true || f0.beats_baselines === 'true';
    fcHtml += '<div style="font-size:12px;color:#555;margin-top:8px">How reliable? We tested on ' + esc(f0.test_rows) + ' past hours the model had never seen. Its typical error was <b>' + fmt(f0.mae_model, 1) + '</b> ug/m3, versus ' + fmt(f0.mae_persistence, 1) + ' for the guess "nothing changes" and ' + fmt(f0.mae_seasonal, 1) + ' for the seasonal average. ' + (beats ? 'The model beats both simple guesses.' : 'The model does NOT currently beat both simple guesses, so treat it with care.') + ' (RMSE: ' + fmt(f0.rmse_model, 1) + ' vs ' + fmt(f0.rmse_persistence, 1) + ' and ' + fmt(f0.rmse_seasonal, 1) + '.)</div>';
  }
}

var banner = problems.length ? '<tr><td style="background:#ffebee;border:2px solid #c62828;padding:10px 16px;color:#c62828;font-size:13px;font-weight:bold">DATA PROBLEM - parts of this report may be incomplete or out of date: ' + esc(problems.join(' | ')) + '</td></tr>' : '';
var sheetLink = '';
var sid = String(cfg.spreadsheet_id || '');
if (sid && sid.charAt(0) !== '<') sheetLink = '<a href="https://docs.google.com/spreadsheets/d/' + esc(sid) + '" style="color:#1565c0">Open the full data in Google Sheets</a>';

function section(title, body) {
  return '<tr><td style="padding:18px 20px 6px;font-size:17px;font-weight:bold;color:#0d47a1;border-top:6px solid #eceff1">' + title + '</td></tr><tr><td style="padding:4px 20px 14px">' + body + '</td></tr>';
}

var today = new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'long' });
var html = '<!DOCTYPE html><html><body style="margin:0;background:#cfd8dc;font-family:Arial,Helvetica,sans-serif;color:#222">';
html += '<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:16px 8px"><table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#fff;border-radius:8px;overflow:hidden">';
html += '<tr><td style="background:#0d47a1;color:#fff;padding:20px"><div style="font-size:12px;letter-spacing:1px">LAHORE SMOKE WATCH - GOVERNMENT BRIEFING</div><div style="font-size:24px;font-weight:bold;margin-top:4px">Where is the smoke worst, and why?</div><div style="font-size:12px;margin-top:6px;opacity:0.85">' + esc(today) + ' | last hotspot check: ' + esc(det ? local(det.run_at) : 'never') + '</div></td></tr>';
html += banner;
html += '<tr><td style="background:' + hc.bg + ';padding:20px;border-bottom:4px solid ' + hc.color + '"><div style="font-size:13px;color:#555">Air in Lahore right now</div><div style="font-size:30px;font-weight:bold;color:' + hc.color + '">' + esc(hc.name) + '</div><div style="font-size:15px;margin-top:2px">PM2.5: <b>' + fmt(headline) + ' ug/m3</b> <span style="font-size:12px;color:#666">(' + (sensorMed !== null ? 'median of ' + sensors.length + ' ground sensors' : 'air-quality model average') + (modelAvg !== null && sensorMed !== null ? '; model says ' + fmt(modelAvg) : '') + ')</span></div><div style="font-size:14px;margin-top:8px"><b>What it means:</b> ' + esc(hc.advice) + '</div></td></tr>';
html += section('1. Where is the smoke worst? (ranked)', '<table width="100%" cellpadding="0" cellspacing="0">' + hotHtml + '</table>');
html += section('2. Why is it happening? (likely causes)', '<table width="100%" cellpadding="0" cellspacing="0">' + causeHtml + '</table><div style="font-size:11px;color:#777;margin-top:4px">These are rule-based estimates marked likely or possible. Each must be confirmed by a field inspection before any action.</div>');
html += section('3. Smoke map of the Lahore region', gridHtml);
html += section('4. What will happen in the next 12 hours?', fcHtml);
html += section('5. Worst readings from ground sensors', '<table width="100%" cellpadding="0" cellspacing="0"><tr><th align="left" style="font-size:11px;color:#777;padding:4px">Place</th><th align="left" style="font-size:11px;color:#777;padding:4px">PM2.5</th><th align="left" style="font-size:11px;color:#777;padding:4px">Level</th></tr>' + sensHtml + '</table>');
html += section('6. Can we trust this report? (data health)', '<table width="100%" cellpadding="0" cellspacing="0">' + srcRows + '</table>');
html += '<tr><td style="padding:16px 20px;background:#eceff1;font-size:11px;color:#555;border-top:6px solid #cfd8dc">' + (sheetLink ? '<div style="font-size:13px;margin-bottom:8px">' + sheetLink + '</div>' : '') + 'PM2.5 means tiny smoke and dust particles that reach deep into the lungs. This is a research prototype built only on public data (Open-Meteo CAMS, NASA FIRMS, OpenAQ, OpenStreetMap); it is not an official government system. Satellites and models are coarse and clouds or haze can hide fires, so results point to an area and cannot prove that a specific business broke the law. Pilot area: Lahore only.</td></tr>';
html += '</table></td></tr></table></body></html>';

var subject = 'Lahore Smoke Report - ' + today + ' - ' + (headline === null ? 'no current data' : hc.name + ' (PM2.5 ' + fmt(headline) + ')') + (problems.length ? ' - DATA PROBLEM' : '');
return [{ json: { subject: subject, html: html, recipient: cfg.recipient } }];

function rows(name) {
  try { return $(name).all().map(function (i) { return i.json; }).filter(function (j) { return j && j.id !== undefined; }); } catch (e) { return []; }
}
function local(iso) { var t = Date.parse(iso); if (!isFinite(t)) return ''; return new Date(t).toLocaleString('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'medium', timeStyle: 'short' }) + ' PKT'; }
function place(lat, lon) {
  var la = Number(lat), lo = Number(lon);
  if (!isFinite(la) || !isFinite(lo)) return '';
  var dn = (la - 31.52) * 111, de = (lo - 74.35) * 95;
  var d = Math.sqrt(dn * dn + de * de);
  if (d < 6) return 'Central Lahore';
  var ang = Math.atan2(de, dn) * 180 / Math.PI; if (ang < 0) ang += 360;
  var names = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
  return Math.round(d) + ' km ' + names[Math.round(ang / 45) % 8] + ' of central Lahore';
}
var out = [];
function add(prefix, list, fn) { list.forEach(function (r) { var o = fn(r); o.row_id = prefix + '-' + o.row_id; out.push({ json: o }); }); }
add('hotspot', rows('Read Hotspots'), function (h) {
  return { row_id: h.id, detected_at: local(h.detected_at), location: place(h.lat, h.lon), lat: h.lat, lon: h.lon, pm25: h.pm25, severity: h.severity, priority_score: h.priority_score, likely_source: h.attribution, confidence: h.attribution_confidence, fires_upwind: h.fires_upwind, fires_nearby: h.fires_nearby, industrial_sites_nearby: h.facilities_nearby, ground_pm25: h.ground_pm25, ground_agreement: h.ground_agreement, evidence: h.evidence, map_link: 'https://www.google.com/maps?q=' + h.lat + ',' + h.lon };
});
add('forecast', rows('Read Forecast'), function (f) {
  return { row_id: f.id, issued_at: f.issued_at, target_time: f.target_time, pm25_now: f.pm25_now, pm25_model: f.pm25_model, pm25_persistence: f.pm25_persistence, pm25_seasonal: f.pm25_seasonal, pm25_cams: f.pm25_cams, mae_model: f.mae_model, mae_persistence: f.mae_persistence, mae_seasonal: f.mae_seasonal, rmse_model: f.rmse_model, rmse_persistence: f.rmse_persistence, rmse_seasonal: f.rmse_seasonal, beats_baselines: f.beats_baselines, train_rows: f.train_rows, test_rows: f.test_rows };
});
add('reading', rows('Read Grid Readings').concat(rows('Read Ground Sensors')), function (o) {
  return { row_id: o.id, observed_at: o.observed_at, source: o.source, cell_id: o.cell_id, lat: o.lat, lon: o.lon, pm25: o.pm25, pm10: o.pm10, no2: o.no2, aod: o.aod, temp_c: o.temp_c, humidity: o.humidity, wind_speed: o.wind_speed, wind_dir: o.wind_dir };
});
add('fire', rows('Read Fires'), function (f) {
  return { row_id: f.id, acq_time: f.acq_time, lat: f.lat, lon: f.lon, frp: f.frp, confidence: f.confidence, satellite: f.satellite, fire_key: f.fire_key };
});
add('site', rows('Read Facilities'), function (f) {
  return { row_id: f.id, facility_type: f.facility_type, name: f.name, lat: f.lat, lon: f.lon, location: place(f.lat, f.lon), osm_key: f.osm_key };
});
